create table if not exists users (telegram_id bigint primary key, username text, first_name text not null default '', points integer not null default 0, created_at timestamptz not null default now());
create table if not exists matches (id uuid primary key default gen_random_uuid(), home_team text not null, away_team text not null, kickoff_at timestamptz not null, home_score integer, away_score integer, status text not null default 'open', created_at timestamptz not null default now());
create table if not exists predictions (id uuid primary key default gen_random_uuid(), match_id uuid not null references matches(id) on delete cascade, telegram_id bigint not null references users(telegram_id) on delete cascade, home_score integer not null, away_score integer not null, points integer not null default 0, created_at timestamptz not null default now(), unique(match_id,telegram_id));
